import{c as a,Q as i,j as r,m as t}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Topical Phase Transitions in Artificial Intelligence Research: Large-Scale Evidence and an Early-Warning Signature for Emerging Topics","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.12828","title":"Topical Phase Transitions in Artificial Intelligence Research: Large-Scale Evidence and an Early-Warning Signature for Emerging Topics","archived_date":"2026-07-12","arxiv_id":"2606.12828","authors":["Rasul Khanbayov","Hasan Kurban"],"domain":"ai-topic-emergence-detection","published_date":"2026-06-11","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-06-11-topical-phase-transitions-ai-research-2606-12828.md","filePath":"research/papers/2026-06-11-topical-phase-transitions-ai-research-2606-12828.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-06-11-topical-phase-transitions-ai-research-2606-12828.md"};function s(o,e,c,l,p,d){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="topical-phase-transitions-in-artificial-intelligence-research" tabindex="-1">Topical Phase Transitions in Artificial Intelligence Research <a class="header-anchor" href="#topical-phase-transitions-in-artificial-intelligence-research" aria-label="Permalink to &quot;Topical Phase Transitions in Artificial Intelligence Research&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本論文把「AI 研究這個領域本身」當作動力系統，用計量科學（scientometrics）方法分析 2017–2025 年五大 AI 會議（ACL、CVPR、ICLR、ICML、NeurIPS）共 80,814 篇主軌論文， 發現主要 AI 主題以「相變」（phase transition）模式擴散：多年維持邊緣狀態， 接著在 1–3 年內跨會議暴增為主流。</p><p><strong>關鍵發現：</strong></p><ul><li>LLM 相關主題在 2025 年成為跨會議主導議題；diffusion models 以類似陡峭幅度崛起</li><li>語言模型方法透過 vision-language models 跨界滲入電腦視覺</li><li>強化學習呈現平滑漸進成長，可與真正的「相變」區辨（非暴增型）</li></ul><p><strong>早期預警訊號</strong>：作者以 2017–2021 資料校準出 4 項 publication-dynamics 早期預警指標， 在 2023–2025 樣本外驗證達成 63% recall（對照 13.5% 的隨機基線）。將此訊號套用於 2025 資料後，標記 reasoning/test-time-compute、agentic AI、multimodal LLM、RAG、world models 為 2026–2028 應持續監控的主題。程式碼已公開於 GitHub。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p><code>phase-transition</code> / <code>topic-emergence</code> / <code>scientometrics</code> 等關鍵詞在 workspace 自有題庫 （<code>research/NEW-DOMAINS/covered_topics.txt</code> + DAILY-TOPICS/WEEKLY-FOCUS/papers 標題詞庫） 命中 <strong>0 次</strong>。Workspace 的既有論文集中於「做 AI 研究」本身（agent/LLM/harness 456 篇）， 但從未研究「AI 研究這個領域如何演化、如何提前偵測新興主題」這個 meta-science 層次—— 與 Routine E 自身「如何系統性發現下一個新領域」高度自我指涉，屬全新邊疆。</p>',8)])])}const u=a(n,[["render",s]]);export{g as __pageData,u as default};
